        password=secret();adminPassword=secret();for(int i=0;i<3;i++){String email="b9"+key().replace("-","")+"@stu.hzcu.edu.cn";emails.add(email);secrets.add(email);var auth=context.getBean(AuthService.class);var challenge=auth.requestCode(email,AuthModels.Purpose.REGISTER);String code=MAIL.code(email,"REGISTER");secrets.add(code);users.add(auth.register(email,password,challenge.challengeId(),code).userId());String token=auth.login(email,password).accessToken();tokens.add(token);secrets.add(token);}
