        var image=new java.awt.image.BufferedImage(4,4,java.awt.image.BufferedImage.TYPE_INT_RGB);var bytes=new ByteArrayOutputStream();ImageIO.write(image,"png",bytes);png=bytes.toByteArray();bytes.reset();ImageIO.write(image,"jpeg",bytes);jpeg=bytes.toByteArray();
        publicBody=secret();publicTitle=secret();draftBody=secret();commentBody=secret();article=createArticle();articleImage=upload("/me/articles/"+article+"/images",key(),"image.png","image/png",png,tokens.getFirst()).data.path("imageId").asString();save(article,0,publicTitle,publicBody+"\n![图](/api/v1/media/images/"+articleImage+")");assertThat(call("POST","/me/articles/"+article+"/publish",Map.of("expectedRevision",1,"requestId",key()),tokens.getFirst()).status).isEqualTo(200);version=db.queryForObject("SELECT public_version_id FROM article WHERE id=?",Long.class,article);
