        assertThat(call("POST","/me/cases","{}",tokens.get(1)).status).isEqualTo(400);assertThat(call("POST","/me/cases","x".repeat(2097153),tokens.get(1)).status).isEqualTo(413);assertThat(call("POST","/admin/cases/"+report+"/claim","x".repeat(2097153),adminTokens.getFirst()).status).isEqualTo(413);
        for(String table:List.of("platform_user","campus_certification")){String column=table.equals("platform_user")?"account_state":"state",pk=table.equals("platform_user")?"id":"user_id",bad=table.equals("platform_user")?"RESTRICTED":"REVOKED",good=table.equals("platform_user")?"ACTIVE":"VALID";db.update("UPDATE "+table+" SET "+column+"=? WHERE "+pk+"=?",bad,users.get(1));try{assertThat(get("/me/cases",tokens.get(1)).status).isEqualTo(403);assertThat(submit(submission("FEEDBACK","BUG",null,null,secret(),List.of(),key()),1).status).isEqualTo(403);}finally{db.update("UPDATE "+table+" SET "+column+"=? WHERE "+pk+"=?",good,users.get(1));}}
