    @Test @Order(12) void fileFailuresPreventFalseBindingOrUploadAndRecoverWithoutTouchingOtherFiles()throws Exception{
        String image=upload("/me/case-images",key(),"evidence.png","image/png",png,tokens.get(1)).data.path("id").asString();Path path=root.resolve("media/objects").resolve(image);byte[] saved=Files.readAllBytes(path);Files.write(path,new byte[]{1,2,3});var body=submission("FEEDBACK","BUG",null,null,secret(),List.of(image),key());long cases=count("community_case");try{assertThat(binary("/media/case-images/"+image,tokens.get(1)).statusCode()).isEqualTo(503);assertThat(submit(body,1).code).isEqualTo("STORAGE_UNAVAILABLE");assertThat(count("community_case")).isEqualTo(cases);}finally{Files.write(path,saved);}assertThat(submit(body,1).status).isEqualTo(200);
        Path temporary=root.resolve("media/temporary"),backup=root.resolve("media/temporary-held");Files.move(temporary,backup);try{assertThat(upload("/me/case-images",key(),"test.png","image/png",png,tokens.get(1)).code).isEqualTo("STORAGE_UNAVAILABLE");}finally{Files.move(backup,temporary);}assertThat(upload("/me/case-images",key(),"test.png","image/png",png,tokens.get(1)).status).isEqualTo(200);
    }
