        long files;try(var paths=Files.list(root.resolve("media/objects"))){files=paths.count();}long images=count("community_case_image");assertThat(fault("business_audit","INSERT","NEW.actor_domain='USER' AND NEW.actor_id="+users.get(1)+" AND NEW.action='CASE_IMAGE_UPLOAD'",()->upload("/me/case-images",key(),"rollback.png","image/png",png,tokens.get(1))).status).isEqualTo(503);assertThat(count("community_case_image")).isEqualTo(images);try(var paths=Files.list(root.resolve("media/objects"))){assertThat(paths.count()).isEqualTo(files);}
