        long id=feedback();String request=key();var replies=race(12,()->claim(id,1,request,0));assertThat(replies).allSatisfy(r->assertThat(r.status).isEqualTo(200));assertThat(replies.stream().map(r->r.data.toString()).distinct().count()).isEqualTo(1);assertThat(revision(id)).isEqualTo(2);assertThat(claim(feedback(),1,request,0).code).isEqualTo("REQUEST_KEY_REUSED");
