        var counts=new ArrayList<Map<String,Object>>();for(long id:named.queryForList("SELECT id FROM community_case WHERE user_id IN (:users) ORDER BY id",args,Long.class)){long rev=revision(id),history=db.queryForObject("SELECT COUNT(*) FROM community_case_history WHERE case_id=?",Long.class,id),audits=db.queryForObject("SELECT COUNT(*) FROM business_audit WHERE object_type='CASE' AND object_id=?",Long.class,id);assertThat(history).isEqualTo(rev);assertThat(audits).isEqualTo(rev);counts.add(Map.of("caseId",id,"revision",rev,"historyEvents",history,"successAudits",audits));}Files.writeString(Path.of("target/batch9-case-reconciliation.json"),JSON.writeValueAsString(counts));assertThat(db.queryForList("SELECT version FROM flyway_schema_history WHERE success=TRUE ORDER BY installed_rank",String.class)).containsExactly("1","2","3","4","5","6","7","8","9");
