    @AfterAll static void cleanup()throws Exception{
        if(context==null)return;try{var named=context.getBean(NamedParameterJdbcTemplate.class);var p=new MapSqlParameterSource("users",users).addValue("emails",emails).addValue("admins",admins);if(!users.isEmpty()){
            var cases=named.queryForList("SELECT id FROM community_case WHERE user_id IN (:users)",p,Long.class);if(!cases.isEmpty()){p.addValue("cases",cases);for(String table:List.of("community_admin_receipt","community_case_history","community_case_comment","community_case_media"))named.update("DELETE FROM "+table+" WHERE case_id IN (:cases)",p);}named.update("DELETE FROM community_case_image WHERE user_id IN (:users)",p);named.update("DELETE FROM community_case WHERE user_id IN (:users)",p);
            named.update("DELETE FROM business_audit WHERE actor_domain='USER' AND actor_id IN (:users)",p);if(!admins.isEmpty())named.update("DELETE FROM business_audit WHERE actor_domain='COMMUNITY_ADMIN' AND actor_id IN (:admins)",p);named.update("DELETE FROM comment_create_receipt WHERE user_id IN (:users)",p);named.update("DELETE FROM comment_image WHERE user_id IN (:users)",p);for(long id:named.queryForList("SELECT id FROM discussion_comment WHERE user_id IN (:users) ORDER BY id DESC",p,Long.class))db.update("DELETE FROM discussion_comment WHERE id=?",id);
            var articles=named.queryForList("SELECT id FROM article WHERE owner_user_id IN (:users)",p,Long.class);if(!articles.isEmpty()){p.addValue("articles",articles);for(String table:List.of("article_publish_request","article_version_image","article_draft_image","article_draft_category","article_draft_source_link","author_create_request","media_image","article_draft"))named.update("DELETE FROM "+table+" WHERE article_id IN (:articles)",p);named.update("UPDATE article SET state='DELETED',public_version_id=NULL WHERE id IN (:articles)",p);named.update("DELETE FROM article_version_category WHERE version_id IN (SELECT id FROM article_version WHERE article_id IN (:articles))",p);named.update("DELETE FROM article_source_link WHERE version_id IN (SELECT id FROM article_version WHERE article_id IN (:articles))",p);named.update("DELETE FROM article_version WHERE article_id IN (:articles)",p);named.update("DELETE FROM article WHERE id IN (:articles)",p);}
            for(String table:List.of("author_contact_setting","author_profile","auth_session","campus_certification"))named.update("DELETE FROM "+table+" WHERE user_id IN (:users)",p);named.update("DELETE FROM email_challenge WHERE email IN (:emails)",p);named.update("DELETE FROM auth_email_gate WHERE email IN (:emails)",p);named.update("DELETE FROM platform_user WHERE id IN (:users)",p);
        }if(!admins.isEmpty()){named.update("DELETE FROM community_admin_session WHERE admin_id IN (:admins)",p);named.update("DELETE FROM community_admin WHERE id IN (:admins)",p);}for(String name:names)db.update("DELETE FROM community_admin_login_gate WHERE name_digest=?",AuthCrypto.tokenDigest(name));
        if(originalArticles!=null){assertThat(db.queryForList("SELECT * FROM article ORDER BY id")).isEqualTo(originalArticles);assertThat(db.queryForList("SELECT * FROM article_version ORDER BY id")).isEqualTo(originalVersions);assertThat(db.queryForList("SELECT * FROM platform_user ORDER BY id")).isEqualTo(originalUsers);assertThat(db.queryForList("SELECT * FROM auth_session ORDER BY id")).isEqualTo(originalSessions);assertThat(db.queryForList("SELECT * FROM coin_event ORDER BY sequence_id")).isEqualTo(originalCoins);for(var item:baseline.entrySet())assertThat(count(item.getKey())).as(item.getKey()).isEqualTo(item.getValue());Files.writeString(Path.of("target/batch9-historical-protection.json"),JSON.writeValueAsString(Map.of("articlesMatched",true,"versionsMatched",true,"usersMatched",true,"sessionsMatched",true,"coinFactsMatched",true,"tableCountsMatched",true)));}
        }finally{context.close();}
    }
